<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import RecordsView from './views/RecordsView.vue'
import StatsView from './views/StatsView.vue'
type Settings = { windowIntervalMs:number; cameraIntervalMs:number; aiIntervalSec:number; cameraEnabled:boolean; aiEnabled:boolean; capturesEnabled:boolean; studyApps:string[]; apiKey:string; debugEnabled:boolean; maxAICallsDay:number; autoStartTracking:boolean }
const settings=reactive<Settings>({windowIntervalMs:1000,cameraIntervalMs:500,aiIntervalSec:30,cameraEnabled:false,aiEnabled:false,capturesEnabled:false,studyApps:[],apiKey:'',debugEnabled:false,maxAICallsDay:1800,autoStartTracking:false})
const active=ref(false), page=ref('概览'), toast=ref(''), newApp=ref(''), today=ref('0 分钟'), currentState=ref('未开始'), currentWindow=ref(''), currentAI=ref('')
const logs=ref<{time:string;level:string;message:string}[]>([])
const records=ref<any[]>([]), dailyStats=ref<any[]>([]), selectedDays=ref(7)
const imageData=ref(''), imageName=ref(''), aiResult=ref(''), aiBusy=ref(false), aiQuota=ref({used:0,limit:1800})
const videoElement=ref<HTMLVideoElement|null>(null), cameraRunning=ref(false), cameraStatus=ref('摄像头尚未启动'), faceDetected=ref(false)
let mediaStream:MediaStream|null=null, cameraTimer:number|undefined, cameraBusy=false
const nav=['概览','记录','统计','设置','调试日志']
const native=!!(window as any).go?.main?.App
const elapsed=computed(()=>today.value)
function notify(message:string){toast.value=message;setTimeout(()=>toast.value='',2600)}
function navigate(item:string){page.value=item;if(item==='记录'){loadRecords();loadQuota()}if(item==='统计')loadStats();if(item==='调试日志')refreshLogs()}
async function load(){if(!native)return;Object.assign(settings,await (window as any).go.main.App.GetSettings());await refreshLogs();await refreshStatus();setInterval(refreshStatus,1000)}
async function refreshStatus(){if(!native)return;const s=await (window as any).go.main.App.Status();active.value=s.active;currentState.value=s.state==='studying'?'学习中':s.state==='slacking'?'非学习窗口':s.active?'识别中':'未开始';currentWindow.value=s.windowTitle||'';currentAI.value=s.aiResult||'';const seconds=s.today?.studying||0;today.value=seconds>=3600?`${Math.floor(seconds/3600)} 小时 ${Math.floor(seconds%3600/60)} 分钟`:`${Math.floor(seconds/60)} 分钟`;}
async function refreshLogs(){if(!native||!settings.debugEnabled){logs.value=[];return}logs.value=await (window as any).go.main.App.GetLogs()}
async function clearLogs(){try{if(native)await (window as any).go.main.App.ClearLogs();await refreshLogs();notify('日志已清空')}catch(e){notify(String(e))}}
async function loadQuota(){if(native)aiQuota.value=await (window as any).go.main.App.AIUsage()}
function chooseImage(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>6*1024*1024){notify('图片请小于 6 MB');return}imageName.value=file.name;const reader=new FileReader();reader.onload=()=>imageData.value=String(reader.result);reader.readAsDataURL(file)}
async function analyzeImage(){if(!imageData.value)return notify('请先选择一张图片');aiBusy.value=true;try{const r=await (window as any).go.main.App.AnalyzeImage(imageData.value);aiResult.value=r.analysis;await loadQuota()}catch(e){aiResult.value=String(e)}finally{aiBusy.value=false}}
async function toggleCamera(){if(cameraRunning.value){stopCamera();return}try{mediaStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});cameraRunning.value=true;settings.cameraEnabled=true;await save();await nextTick();if(videoElement.value){videoElement.value.srcObject=mediaStream;await videoElement.value.play()}cameraStatus.value='摄像头已连接，开始本地检测';cameraTimer=window.setInterval(detectCameraFrame,Math.max(500,settings.cameraIntervalMs))}catch(e){cameraStatus.value='无法打开摄像头：'+String(e);settings.cameraEnabled=false;if(native)await (window as any).go.main.App.SetCameraSignal(false,String(e))}}
async function detectCameraFrame(){if(!cameraRunning.value||cameraBusy||!videoElement.value||videoElement.value.videoWidth===0)return;cameraBusy=true;try{const v=videoElement.value,c=document.createElement('canvas');c.width=480;c.height=Math.round(480*v.videoHeight/v.videoWidth);c.getContext('2d')!.drawImage(v,0,0,c.width,c.height);const found=await (window as any).go.main.App.DetectFace(c.toDataURL('image/jpeg',0.55));faceDetected.value=found;cameraStatus.value=found?'检测到人脸':'未检测到人脸';await (window as any).go.main.App.SetCameraSignal(found,'')}catch(e){cameraStatus.value='检测错误：'+String(e);await (window as any).go.main.App.SetCameraSignal(false,String(e))}finally{cameraBusy=false}}
function stopCamera(){if(cameraTimer)window.clearInterval(cameraTimer);cameraTimer=undefined;mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;cameraRunning.value=false;faceDetected.value=false;settings.cameraEnabled=false;cameraStatus.value='摄像头已关闭';if(native)(window as any).go.main.App.SetCameraSignal(false,'摄像头已关闭');save()}
async function loadRecords(){if(native)records.value=await (window as any).go.main.App.GetSegments(30)}
async function loadStats(){if(native)dailyStats.value=await (window as any).go.main.App.GetDailyStats(selectedDays.value)}
async function editRecord(r:any,e:Event){try{await (window as any).go.main.App.EditSegment(r.id,(e.target as HTMLSelectElement).value);await loadRecords();notify('记录已修正')}catch(err){notify(String(err))}}
async function exportCSV(){try{const p=await (window as any).go.main.App.ExportCSV(30);if(p)notify('已导出 '+p)}catch(e){notify(String(e))}}
async function save(){try{if(native)await (window as any).go.main.App.SaveSettings({...settings,studyApps:[...settings.studyApps]});await refreshLogs();notify('设置已保存并生效')}catch(e){notify(String(e))}}
async function toggle(){try{if(native){const s=active.value?await (window as any).go.main.App.StopTracking():await (window as any).go.main.App.StartTracking();active.value=s.active;await refreshStatus()} else active.value=!active.value;notify(active.value?'开始记录':'已暂停')}catch(e){notify(String(e))}}
function addApp(){const value=newApp.value.trim();if(value&&!settings.studyApps.includes(value)){settings.studyApps.push(value);newApp.value='';save()}}
onMounted(()=>{load();loadQuota()})
</script>
<template><div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">学</div><div><b>学习时长统计</b><small>专注 · 记录 · 复盘</small></div></div><div class="nav-label">工作台</div><button v-for="(item,i) in nav.filter(x=>x!=='调试日志'||settings.debugEnabled)" :key="item" class="nav-item" :class="{selected:page===item}" @click="page=item;item==='调试日志'&&refreshLogs()"><span class="nav-icon">{{['◫','◷','▥','⚙','≋'][i]}}</span>{{item}}<span v-if="page===item" class="nav-dot"></span></button><div class="sidebar-bottom"><div class="privacy"><span class="privacy-icon">✳</span><div><b>数据保存在本机</b><small>你的记录仅你可见</small></div></div><div class="profile"><div class="avatar">我</div><div><b>个人空间</b><small>本地用户</small></div><span class="more">···</span></div></div></aside><main class="main"><header><div class="crumb">工作台 <span>/</span> <b>{{page}}</b></div><div class="header-right"><span class="local"><i></i>本地运行</span><div class="avatar small">我</div></div></header><section class="content"><template v-if="page==='概览'"><div class="page-title"><div><div class="eyebrow">{{new Date().toLocaleDateString('zh-CN',{weekday:'long',month:'long',day:'numeric'})}}</div><h1>保持节奏，稳步向前。</h1><p>每一段专注，都值得被看见。</p></div><button class="primary" :class="{stop:active}" @click="toggle"><span>{{active?'Ⅱ':'▶'}}</span>{{active?'暂停记录':'开始记录'}}</button></div><div class="hero-card"><div class="hero-main"><div class="hero-label"><span class="live-dot" :class="{live:active}"></span>{{active?'正在记录':'尚未开始记录'}}</div><div class="hero-time">{{elapsed}}<small>今日学习</small></div><div class="hero-foot">{{active?'计时已启动，学习状态正在综合判断':'开始记录后，前台窗口与可选信号将协助判断学习状态'}}</div></div><div class="hero-side"><div class="side-title">当前状态 <span>实时</span></div><div class="state-pill"><i></i> {{currentState}}</div><div class="side-line"></div><div class="side-caption">判定信号</div><div class="signals"><span>▣ {{currentWindow||'前台窗口待检测'}}</span><span>{{cameraRunning?(faceDetected?'◉ 检测到人脸':'◉ 摄像头已连接'):'◉ 摄像头关闭'}}</span><span>{{settings.aiEnabled?'✧ AI 分析':'✧ AI 分析关闭'}}</span><span v-if="currentAI" class="ai-current">{{currentAI}}</span></div></div></div><div class="section-heading"><div><h2>今日概览</h2><p>学习时间与状态分布</p></div><button class="text-button" @click="page='统计'">查看统计 <span>→</span></button></div><div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-icon blue">◷</span><span class="trend">今日</span></div><div class="stat-number">0<span>分钟</span></div><div class="stat-name">有效学习</div><div class="mini-bars"><i v-for="n in 18" :key="n" :style="{height:(12+(n*17%32))+'px'}"></i></div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon green">▣</span><span class="trend">窗口采样</span></div><div class="stat-number">{{(1000/settings.windowIntervalMs).toFixed(1)}}<span>/秒</span></div><div class="stat-name">前台窗口检查频率</div><div class="subnote">每 {{settings.windowIntervalMs}} 毫秒采样一次</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon violet">✧</span><span class="trend">可选</span></div><div class="stat-number">{{settings.aiEnabled?'开启':'关闭'}}</div><div class="stat-name">AI 内容分析</div><div class="subnote">{{settings.aiEnabled?`每 ${settings.aiIntervalSec} 秒分析一次`:'未启用，不发送网络请求'}}</div></article></div><div class="bottom-grid"><article class="panel week-panel"><div class="panel-head"><div><h3>近 7 天学习趋势</h3><p>每日有效学习时长</p></div><span class="period">近 7 天⌄</span></div><div class="empty-chart"><div class="chart-lines"><i></i><i></i><i></i><i></i></div><div class="chart-empty"><span>▥</span><b>还没有学习记录</b><small>开始记录后，这里会显示你的学习趋势</small></div><div class="days"><span>周一</span><span>周二</span><span>周三</span><span>周四</span><span>周五</span><span>周六</span><span>周日</span></div></div></article><article class="panel"><div class="panel-head"><div><h3>状态分布</h3><p>今日时间构成</p></div><button class="dots">···</button></div><div class="donut-wrap"><div class="donut"><div><b>—</b><small>暂无数据</small></div></div></div><div class="legend"><span><i class="c1"></i>学习中 <b>—</b></span><span><i class="c2"></i>摸鱼 <b>—</b></span><span><i class="c3"></i>离座 <b>—</b></span></div></article></div></template><template v-else-if="page==='设置'"><div class="page-title"><div><div class="eyebrow">偏好设置</div><h1>设置你的学习方式。</h1><p>调整采样、信号来源和隐私选项。</p></div><button class="primary" @click="save">保存设置</button></div><div class="settings-layout"><nav class="settings-nav"><a class="active">采样间隔</a><a>窗口规则</a><a>AI 分析</a><a>摄像头</a><a>数据与隐私</a></nav><div class="settings-body"><section class="setting-card"><div class="setting-title"><div><h3>信号采样间隔</h3><p>设置应用检查各类信号的频率。更短的间隔会增加资源占用。</p></div><span class="setting-glyph">◷</span></div><label class="field"><span>前台窗口采样</span><div class="input-unit"><input type="number" min="250" max="10000" step="250" v-model.number="settings.windowIntervalMs"><em>毫秒</em></div><small>建议 500–2000 毫秒，范围 250–10000 毫秒</small></label><label class="field"><span>摄像头采样</span><div class="input-unit"><input type="number" min="100" max="5000" step="100" v-model.number="settings.cameraIntervalMs"><em>毫秒</em></div><small>建议 300–1000 毫秒，范围 100–5000 毫秒</small></label><label class="field"><span>AI 内容分析间隔</span><div class="input-unit"><input type="number" min="10" max="3600" step="5" v-model.number="settings.aiIntervalSec"><em>秒</em></div><small>建议至少 30 秒，范围 10–3600 秒</small></label></section><section class="setting-card"><div class="setting-title"><div><h3>信号来源</h3><p>你可以随时关闭可选信号。基础窗口记录仍可独立运行。</p></div><span class="setting-glyph">⌁</span></div><div class="toggle-row"><div><b>摄像头辅助判断</b><small>使用 YuNet 在本地检测人脸，不做身份识别</small></div><button class="switch" :class="{on:settings.cameraEnabled}" @click="toggleCamera"><i></i></button></div><div v-if="cameraRunning" class="camera-preview"><video ref="videoElement" autoplay muted playsinline></video><div class="camera-state" :class="{found:faceDetected}"><i></i>{{cameraStatus}}</div></div><div v-else class="camera-hint">{{cameraStatus}}</div><div class="toggle-row"><div><b>AI 窗口内容分析</b><small>仅在填写 API Key 后启用；分析失败时自动忽略</small></div><button class="switch" :class="{on:settings.aiEnabled}" @click="settings.aiEnabled=!settings.aiEnabled"><i></i></button></div><div v-if="settings.aiEnabled" class="field key-field"><span>API Key</span><input type="password" autocomplete="off" placeholder="输入服务商 API Key" v-model="settings.apiKey"><small>仅保存在本机配置中，请勿在共享设备保存。</small></div><div class="field"><span>每日 AI 调用上限</span><div class="input-unit"><input type="number" min="1" max="2000" v-model.number="settings.maxAICallsDay"><em>次</em></div><small>建议预留额度；GLM 免费额度按服务商账户规则为准，应用硬上限最多 2000 次。</small></div><div class="toggle-row"><div><b>调试模式</b><small>启用运行日志查看入口，日志不包含图片内容或 API Key。</small></div><button class="switch" :class="{on:settings.debugEnabled}" @click="settings.debugEnabled=!settings.debugEnabled"><i></i></button></div><div class="toggle-row"><div><b>状态变化截图</b><small>截图只保存在本机，可在记录页管理</small></div><button class="switch" :class="{on:settings.capturesEnabled}" @click="settings.capturesEnabled=!settings.capturesEnabled"><i></i></button></div></section><section class="setting-card"><div class="setting-title"><div><h3>启动行为</h3><p>选择应用启动后是否立即开始记录。</p></div><span class="setting-glyph">▶</span></div><div class="toggle-row"><div><b>启动后自动开始记录</b><small>应用打开后自动采集前台窗口并计时，可随时暂停。</small></div><button class="switch" :class="{on:settings.autoStartTracking}" @click="settings.autoStartTracking=!settings.autoStartTracking"><i></i></button></div></section><section class="setting-card"><div class="setting-title"><div><h3>调试模式</h3><p>启用后记录应用启动、设置变更和计时操作。</p></div><span class="setting-glyph">≋</span></div><div class="toggle-row"><div><b>启用调试日志</b><small>日志保存在本机应用配置目录 app.log</small></div><button class="switch" :class="{on:settings.debugEnabled}" @click="settings.debugEnabled=!settings.debugEnabled"><i></i></button></div></section><section class="setting-card"><div class="setting-title"><div><h3>学习应用白名单</h3><p>用于辅助判断当前前台应用是否与学习相关。</p></div><span class="setting-glyph">▣</span></div><div class="app-entry"><input v-model="newApp" placeholder="输入应用名称或进程名，例如 Code.exe" @keyup.enter="addApp"><button class="secondary" @click="addApp">添加</button></div><div v-if="settings.studyApps.length" class="chips"><span v-for="app in settings.studyApps" :key="app">{{app}}<button @click="settings.studyApps=settings.studyApps.filter(x=>x!==app)">×</button></span></div><div v-else class="muted-note">尚未添加应用</div></section><div class="settings-actions"><span>设置会保存在本机</span><button class="primary" @click="save">保存设置</button></div></div></div></template><template v-else-if="page==='调试日志'"><div class="page-title"><div><div class="eyebrow">诊断信息</div><h1>运行日志。</h1><p>仅在调试模式启用时保存，最近 1000 条记录。</p></div><div><button class="secondary" @click="refreshLogs">刷新</button> <button class="secondary" @click="clearLogs">清空</button></div></div><div class="panel log-panel"><div v-if="!logs.length" class="muted-note">暂无日志。启用调试模式并进行操作后，日志会显示在这里。</div><div v-for="(log,i) in logs" :key="i" class="log-row"><time>{{new Date(log.time).toLocaleString()}}</time><b :class="'log-'+log.level.toLowerCase()">{{log.level}}</b><span>{{log.message}}</span></div></div></template><template v-else-if="page==='调试日志'"><div class="page-title"><div><div class="eyebrow">诊断信息</div><h1>运行日志。</h1><p>仅在调试模式启用时保存，最近 1000 条。</p></div><div><button class="secondary" @click="refreshLogs">刷新</button> <button class="secondary" @click="clearLogs">清空</button></div></div><div class="panel log-panel"><div v-if="!logs.length" class="muted-note">暂无日志</div><div v-for="(log,i) in logs" :key="i" class="log-row"><time>{{new Date(log.time).toLocaleString()}}</time><b>{{log.level}}</b><span>{{log.message}}</span></div></div></template><template v-else><div class="page-title"><div><div class="eyebrow">{{page==='记录'?'学习历史':'数据洞察'}}</div><h1>{{page==='记录'?'每一段时间，都有迹可循。':'看见自己的长期投入。'}}</h1><p>{{page==='记录'?'查看并修正历史状态片段。':'从趋势中发现适合自己的节奏。'}}</p></div><button class="secondary">{{page==='记录'?'导出 CSV':'近 30 天⌄'}}</button></div><div v-if="page==='记录'" class="panel ai-image-card"><h3>手动分析截图</h3><p>选择屏幕截图，调用 GLM-4.6V-Flash 分析学习相关性；只有点击分析时才会上传。</p><input type="file" accept="image/png,image/jpeg,image/webp" @change="chooseImage"><span v-if="imageName" class="muted-note">{{imageName}}</span><div class="ai-actions"><button class="primary" :disabled="!imageData||aiBusy" @click="analyzeImage">{{aiBusy?'分析中…':'分析图片'}}</button><small>今日已用 {{aiQuota.used}} / {{aiQuota.limit}} 次</small></div><div v-if="aiResult" class="ai-result">{{aiResult}}</div></div><RecordsView v-if="page==='记录'"/><StatsView v-if="page==='统计'"/><div v-if="page!=='记录'&&page!=='统计'" class="panel blank-page"><div class="blank-icon">{{page==='记录'?'◷':'▥'}}</div><b>记录开始后，这里会逐渐丰富</b><span>你的时间片、状态分布和长期趋势将显示在这里。</span><button class="text-button" @click="page='设置'">先配置采样与信号 →</button></div></template></section><footer>学习时长统计 <span>·</span> 专注你的每一天 <span class="version">v1.0.0 · 本地优先</span></footer></main><div v-if="toast" class="toast">{{toast}}</div></div></template>











